NOTE TITLE: [[MOC]]

METADATA:{"type":"moc","matière":null,"tags":["moc"],"date_creation":"<% tp.date.now(\"YYYY-MM-DD\") %>","created":"2026/07/26 20:46:39","modified":"2026/07/26 21:02:32","chunkId":"06 Templates/MOC.md#0","heading":"${sujet}"}

NOTE BLOCK CONTENT:

<%*
let sujet = await tp.system.prompt("Nom du sujet");

// Met la première lettre en majuscule
sujet = sujet.charAt(0).toUpperCase() + sujet.slice(1);

// Création du tag en minuscules
let tag = sujet
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replaceAll(" ", "/");

await tp.file.rename("MOC "+sujet);

tR += `
# ${sujet}

\`\`\`dataview
LIST WITHOUT ID
file.link
FROM #math/${tag} AND #concepts
SORT file.name
\`\`\`
`;
%>

